import{_ as a,C as n,o as e,c as g,a2 as r,j as d,a as o,E as l}from"./chunks/framework.CHeM0PsO.js";const i="/assets/shu_tiao_cui.D1TsIhyK.jpg",_=JSON.parse('{"title":"00 · Brief 与解读","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/00-brief.md","filePath":"lab/shuangyu-fries/00-brief.md","lastUpdated":1787456457000}'),h={name:"lab/shuangyu-fries/00-brief.md"},p={id:"_3-日文元素-定性未明-是风险不是资产",tabindex:"-1"};function c(b,t,u,f,m,k){const s=n("Badge");return e(),g("div",null,[t[3]||(t[3]=r('<h1 id="_00-·-brief-与解读" tabindex="-1">00 · Brief 与解读 <a class="header-anchor" href="#_00-·-brief-与解读" aria-label="Permalink to &quot;00 · Brief 与解读&quot;">​</a></h1><blockquote><p>阶段 0 · 立项 ｜ 2026-08-05</p></blockquote><h2 id="客户原话" tabindex="-1">客户原话 <a class="header-anchor" href="#客户原话" aria-label="Permalink to &quot;客户原话&quot;">​</a></h2><blockquote><p>「做两支广告。」</p></blockquote><p>加一张产品图。工艺方面客户明确说了是 <strong>VF（真空低温油炸）</strong>。</p><p><strong>除此之外没有别的信息。</strong> 渠道、时长、预算、交期、投放目的全部未定，由我方提案。</p><div class="warning custom-block"><p class="custom-block-title">这是最典型的一种开局</p><p>不是信息不足，是<strong>客户自己也还没想清楚</strong>。这种情况下提案的第一价值不是创意，是<strong>把问题结构化地摆出来让客户做选择</strong>——他做完选择，brief 就有了。</p></div><h2 id="产品图" tabindex="-1">产品图 <a class="header-anchor" href="#产品图" aria-label="Permalink to &quot;产品图&quot;">​</a></h2><p><img src="'+i+'" alt="双宇食品 薯条脆 番茄味 46g"></p><h2 id="从图上能确认的事实" tabindex="-1">从图上能确认的事实 <a class="header-anchor" href="#从图上能确认的事实" aria-label="Permalink to &quot;从图上能确认的事实&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>品牌</td><td>双宇食品（绿色盾形 logo，带 ® 注册标）</td></tr><tr><td>产品名</td><td>薯条脆</td></tr><tr><td>口味</td><td>番茄味</td></tr><tr><td>规格</td><td><strong>净含量 46 克</strong></td></tr><tr><td>包装形态</td><td><strong>纸杯装</strong> + 铝箔封口 + 可复盖的塑料圆盖</td></tr><tr><td>包装文案</td><td>「原薯鲜切」（侧面）、「开启畅乐 由此撕开」（盖顶）</td></tr><tr><td>日文副标</td><td>カリカリポテトフライ（脆脆薯条）</td></tr><tr><td>主视觉</td><td>高饱和橙底 + 深红撕纸块 + 白色主标字，图上有薯条与土豆的实物图</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">这张图是渲染图，不是实拍</p><p>干净的渐变背景、完美的表面反射、无任何瑕疵——这是 3D 渲染或高度精修的效果图。</p><p><strong>影响很直接</strong>：成片里包装出镜必须用实拍或设计源文件，<a href="/tools/decision-tree#a1-产品必须精确还原吗">选型决策树 A1</a> 已经写死了这一条。而我们现在手上既没有实拍，也没有源文件，<strong>只有一张不知道能不能商用的渲染图</strong>。</p><p>这是物料清单的第一优先级。</p></div><h2 id="我们的解读" tabindex="-1">我们的解读 <a class="header-anchor" href="#我们的解读" aria-label="Permalink to &quot;我们的解读&quot;">​</a></h2><h3 id="_1-卖点冲突-客户想讲-vf-包装上主打「原薯鲜切」" tabindex="-1">① 卖点冲突：客户想讲 VF，包装上主打「原薯鲜切」 <a class="header-anchor" href="#_1-卖点冲突-客户想讲-vf-包装上主打「原薯鲜切」" aria-label="Permalink to &quot;① 卖点冲突：客户想讲 VF，包装上主打「原薯鲜切」&quot;">​</a></h3><p><strong>包装通篇没有出现「VF」「真空」「低温油炸」任何一个字。</strong> 主打的是「原薯鲜切」。</p><p>这两个是<strong>不同层面的卖点</strong>：</p><table tabindex="0"><thead><tr><th></th><th>说的是什么</th><th>对立面是什么</th></tr></thead><tbody><tr><td><strong>原薯鲜切</strong></td><td>原料形态——真土豆切的</td><td>薯粉压模成型（复合薯片）</td></tr><tr><td><strong>VF 工艺</strong></td><td>加工方式——真空低温油炸</td><td>常压高温油炸</td></tr></tbody></table><p>片子讲一个包装上不存在的概念，消费者拿到手对不上，反而伤信任。这条必须在提案里给客户一个说法。</p><h3 id="_2-46g-杯装-不是袋装" tabindex="-1">② 46g 杯装，不是袋装 <a class="header-anchor" href="#_2-46g-杯装-不是袋装" aria-label="Permalink to &quot;② 46g 杯装，不是袋装&quot;">​</a></h3><p>杯装带来的差异，全都是袋装没有的：</p><table tabindex="0"><thead><tr><th></th><th>意味着什么</th></tr></thead><tbody><tr><td>有开盖动作</td><td><strong>撕铝箔封口</strong>是一个干净、有声音、有仪式感的动作——袋装的「撕开」远没这么好看</td></tr><tr><td>可复盖</td><td>「吃不完盖上」是一个真实使用场景</td></tr><tr><td>46g 单人份</td><td>即食装，指向便利店 / 零食集合店 / 办公室场景，<strong>不一定以电商详情页为主</strong></td></tr><tr><td>杯身可立</td><td>桌面场景、分享场景成立</td></tr></tbody></table>',21)),d("h3",p,[t[0]||(t[0]=o("③ 日文元素：定性未明，是风险不是资产 ",-1)),l(s,{type:"tip",text:"2026-08-06 已定性"}),t[1]||(t[1]=o()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#_3-日文元素-定性未明-是风险不是资产","aria-label":'Permalink to "③ 日文元素：定性未明，是风险不是资产 <Badge type="tip" text="2026-08-06 已定性" />"'},"​",-1))]),t[4]||(t[4]=r('<p>副标「カリカリポテトフライ」是日文。</p><div class="danger custom-block"><p class="custom-block-title">这条不能自己猜</p><ul><li>如果产品<strong>真有日本背景</strong>（日本技术、日方合作、出口日本），日式调性可以做，且是好资产。</li><li>如果只是<strong>视觉风格上的借用</strong>，那么片子里做日式调性、出现日本场景或暗示进口，<strong>属于虚假宣传</strong>。</li></ul><p>包装上印日文本身是行业常见做法，法律上通常不构成问题；但<strong>广告是另一回事</strong>——广告里主动暗示「这是日本的」，性质完全不同。</p><p><strong>这条直接进物料清单，不自己判断。</strong></p></div><div class="tip custom-block"><p class="custom-block-title">2026-08-06 已定性：纯装饰</p><p>客户明确答复——<strong>日文副标只是装饰，与日本无任何技术、合作或出口关系。</strong></p><p>处理方式不变（片中不出现日式元素），但这条从「风险」变成了「已知条件」。</p><p><strong>而作为已知条件，它比作为风险时更有用</strong>：既然日文没有任何实质支撑，它在包装上就只剩借力效果——<strong>指向的还是别人的心智</strong>。由此新增一条执行约束：包装出镜时不刻意突出日文副标。完整推理见 <a href="./#③-日文元素-定性前一律不碰">项目首页决议 ③</a>。</p><p>上面那段「不能自己猜」的原文保留不动。<strong>当时不猜是对的</strong>——如果当时按「视觉借用」自行判断并据此做了日式调性，现在拿到的答案会证明那是虚假宣传；如果按「可能有背景」保守处理，又会白白绕路。<strong>答案是哪个都不重要，重要的是当时没有资格猜。</strong></p></div><h2 id="客户补充物料-·-vf-工艺资料" tabindex="-1">客户补充物料 · VF 工艺资料 <a class="header-anchor" href="#客户补充物料-·-vf-工艺资料" aria-label="Permalink to &quot;客户补充物料 · VF 工艺资料&quot;">​</a></h2><blockquote><p>2026-08-06 ｜ 客户以文字形式提供，无附件、无出处标注</p></blockquote><h3 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h3><blockquote><p><strong>VF —— 真空低温脱水技术（又称低温油浴技术）</strong></p><p>VF 技术多用于果蔬脆片生产。该技术融合真空技术与油炸脱水原理：在负压低温环境下，以热油作为传热介质，让果蔬内部水分快速蒸发干燥，形成疏松多孔结构；全程油温恒定控制在 80~90℃，依靠油的导热性析出食材内部水分，加工完成后通过离心工艺去除食材表面多余油脂。</p><p><strong>一、核心工艺特点</strong> 核心为低温油炸模式，真空低温环境下加工不会生成丙烯酰胺，生产全程无需额外添加化学添加剂，能稳定保留钙、铁、膳食纤维等耐热营养物质。</p><p><strong>二、成品产品五大特点</strong></p><ol><li>口感：整体酥脆干爽，吃完无油腻感；</li><li>原味留存：完整锁住果蔬天然色泽、原生营养与本身风味；</li><li>安全健康：无化学添加剂，规避传统高温油炸带来的致癌风险；</li><li>食用灵活：可直接干吃，也可泡水复水食用，复水后口感接近新鲜果蔬；</li><li>营养低脂：低脂肪、低热量、高膳食纤维，富含多种维生素与微量元素。</li></ol></blockquote><h3 id="第一判断-这不是薯条脆的工艺文件" tabindex="-1">第一判断：这不是薯条脆的工艺文件 <a class="header-anchor" href="#第一判断-这不是薯条脆的工艺文件" aria-label="Permalink to &quot;第一判断：这不是薯条脆的工艺文件&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">通篇讲的是「果蔬脆片」，不是这个产品</p><p>证据最硬的是<strong>第 4 条</strong>：「可泡水复水食用，复水后口感接近新鲜果蔬」。</p><p>薯条脆没有人会泡水吃，泡了产品就毁了。这句话只有放在苹果脆、秋葵脆、香菇脆这类果蔬脆片语境下才成立。</p><p>其余佐证：全文主语是「果蔬」「食材」，从头到尾没有出现「土豆」「马铃薯」「薯条」一次。</p><p><strong>这是一份 VF 技术的通用介绍/推广口径</strong>——可能来自设备商、代工厂或技术方的宣传材料，被整段转给了我们。它能说明这门技术是什么，<strong>不能证明这个产品是怎么做的</strong>。</p></div><p>因此物料清单第 2 项判定为<strong>部分到位</strong>，而不是完成。</p><h3 id="能用的-三样东西" tabindex="-1">能用的：三样东西 <a class="header-anchor" href="#能用的-三样东西" aria-label="Permalink to &quot;能用的：三样东西&quot;">​</a></h3><table tabindex="0"><thead><tr><th>拿到了什么</th><th>用在哪</th><th>为什么能用</th></tr></thead><tbody><tr><td><strong>「疏松多孔结构」</strong></td><td>断面镜头的物理依据</td><td>这是「为什么脆」的机制解释，也是画面抓手。提案里 A 片「断面透光」那一镜，原本只是好看，现在有了内容——<strong>光能透过去，是因为里面是多孔的</strong></td></tr><tr><td><strong>「80~90℃」</strong></td><td>可做字幕的具体数字</td><td>事实陈述，不是宣称，风险低。且它自带对比而不必说出对比对象——常压油炸在什么温度，观众自己知道</td></tr><tr><td><strong>「离心去除表面多余油脂」</strong></td><td>回应「油炸=油腻」</td><td>这是一道<strong>工序</strong>，不是一个形容词。说「有一道脱油工序」和说「低脂」是完全不同性质的两句话，前者可查证、后者要检测报告</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">第三样最值钱</p><p>产品的天然弱点是「它是油炸的」。<strong>脱油离心是这份资料里唯一一个能正面回应这个弱点、且不需要任何检测数据支撑的东西</strong>——因为它陈述的是工序的存在，不是营养的结论。</p><p>而且它有画面：离心机高速旋转。这是实拍拍不到、生成擅长的区间。</p></div><h3 id="不能用的-逐条裁定" tabindex="-1">不能用的：逐条裁定 <a class="header-anchor" href="#不能用的-逐条裁定" aria-label="Permalink to &quot;不能用的：逐条裁定&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原文表述</th><th>判定</th><th>理由</th></tr></thead><tbody><tr><td>加工<strong>不会生成丙烯酰胺</strong></td><td>🔴 <strong>不进片</strong></td><td>双重问题。「不会」是绝对化，需检测报告，且「未检出」≠「不会生成」；更要命的是<strong>丙烯酰胺是 2A 类致癌物</strong>，广告里主动提它——哪怕是说自己没有——等于引入致癌话题并暗示同类产品有害</td></tr><tr><td><strong>规避传统高温油炸带来的致癌风险</strong></td><td>🔴 <strong>绝对不进片</strong></td><td><strong>整份材料里风险最高的一句。</strong> 三重违规：涉及疾病的表述、与同类产品直接对比、暗示食品具有防病作用。这条同时踩中提案「内容边界」里已列明的两项</td></tr><tr><td><strong>低脂肪、低热量、高膳食纤维、富含多种维生素</strong></td><td>🔴 <strong>不采信</strong></td><td>四个都是有国家标准量化门槛的含量声称，须本产品实测达标并规范标示。<strong>而油炸薯类产品达到「低脂」「低热量」门槛的可能性极低。</strong> 在拿到营养成分表之前，我方不引用这四个词中的任何一个</td></tr><tr><td>无需添加<strong>化学添加剂</strong> / <strong>无化学添加剂</strong></td><td>🟡 <strong>需配料表 + 改表述</strong></td><td>「化学添加剂」不是法定概念——食品添加剂是有目录的合法品类，这个词本身站不住。且「无添加」类宣称有专门规范。配料表干净的话可以说，但要换成规范说法</td></tr><tr><td><strong>完整锁住</strong>天然色泽、<strong>原生营养</strong>与风味</td><td>🟡 <strong>拆开处理</strong></td><td>「完整」是绝对化用语，删。<strong>色泽和风味可以留</strong>——那是消费者眼睛和嘴巴能验证的感官事实；「原生营养」删，属营养声称</td></tr><tr><td><strong>稳定保留</strong>钙、铁、膳食纤维等</td><td>🟡 <strong>需数据</strong></td><td>营养成分声称，且「保留」的比较基准未给（相对于鲜薯？相对于高温油炸？）。无基准的「保留」是空话</td></tr><tr><td>酥脆干爽、<strong>吃完无油腻感</strong></td><td>🟢 <strong>可用</strong></td><td>感官描述，不是营养声称。<strong>这是五条里唯一可以原样进片的</strong>，而且正好和脱油工序互为表里：一个说工序，一个说结果</td></tr><tr><td>可泡水复水食用</td><td>⬜ <strong>不适用</strong></td><td>见上，这条属于果蔬脆片，不属于本产品</td></tr></tbody></table><h3 id="这份资料对已有决议的影响" tabindex="-1">这份资料对已有决议的影响 <a class="header-anchor" href="#这份资料对已有决议的影响" aria-label="Permalink to &quot;这份资料对已有决议的影响&quot;">​</a></h3><p><strong>决议 ① 鲜切主、VF 支撑 —— 更稳固了，理由和原来不同。</strong></p><p>原来的理由是「包装上没有 VF、消费者听不懂」。现在多了一条更硬的：</p><div class="warning custom-block"><p class="custom-block-title">客户给了 VF 一大堆料，但能用的只有两个感官词和一道工序</p><p>资料里最有传播力的四句话（不致癌、低脂、高纤维、无添加），<strong>没有一句能在拿到检测数据前使用</strong>。</p><p>剩下能用的是「多孔结构」「80~90℃」「脱油离心」「不油腻」——这些是<strong>很好的支撑证据，但撑不起一个主标题</strong>。它们回答的是「为什么脆而不腻」，不是「为什么买它」。</p><p><strong>这恰恰就是提案里给 VF 安排的位置。</strong> 资料到手后，这个安排从判断变成了事实。</p></div><p><strong>决议 ③ 日文元素 —— 不受影响</strong>，客户本轮未回应此项，继续按「无日本背景」处理。</p><p><strong>提案 v1.0 不改动。</strong> 初稿曾主张扩充「内容边界」一节，依据是「客户发材料即希望片中使用」——<strong>该推断已撤回</strong>。这份材料的性质是对内的产品认知口径，客户并未主张这些表述进入成片。提案原有的五条红线已覆盖此处风险。</p><div class="tip custom-block"><p class="custom-block-title">留档一条方法教训</p><p>「从文本推断意图」在客户沟通里是高频错误。同一份材料，「你参考一下」和「按这个写」在文本上没有区别，<strong>区别只存在于发送时的语境里</strong>。</p><p>下次客户主动发来材料，先确认它是<strong>参考件</strong>还是<strong>要求件</strong>，再决定动不动提案。</p></div><h3 id="由此新增的索要项" tabindex="-1">由此新增的索要项 <a class="header-anchor" href="#由此新增的索要项" aria-label="Permalink to &quot;由此新增的索要项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>新增索要</th><th>为什么现在才提</th></tr></thead><tbody><tr><td>2a</td><td><strong>这份资料的出处</strong>——设备商 / 代工厂 / 技术方 / 客户自撰</td><td>决定它能否作为宣称依据。转述的宣传稿不能背书，技术方盖章的文件可以</td></tr><tr><td>2b</td><td><strong>薯条脆的实际工艺参数</strong>是否就是 80~90℃</td><td>通用范围 ≠ 本产品参数。要做成字幕的数字，必须是这个产品的</td></tr><tr><td>2c</td><td>若要使用「不含丙烯酰胺」「低脂」任一表述，需<strong>第三方检测报告</strong></td><td>客户若坚持要用，这是唯一路径。<strong>先说清楚，比事后拒绝好</strong></td></tr><tr><td>2d</td><td><strong>是否有脱油工序、脱油后的含油量</strong></td><td>这是我方最想用的一条，需要确认本产品确实有这道工序</td></tr></tbody></table><p>原清单第 3 项（配料表与营养成分表）<strong>优先级由必须项升为最急项</strong>——上表七条待定裁定里，有五条要靠它才能结案。</p><h2 id="同轮口头反馈" tabindex="-1">同轮口头反馈 <a class="header-anchor" href="#同轮口头反馈" aria-label="Permalink to &quot;同轮口头反馈&quot;">​</a></h2><blockquote><p>2026-08-06 ｜ 与工艺资料同轮获知，均为口头，<strong>尚无书面确认</strong></p></blockquote><h3 id="_1-投放渠道-抖音短视频-电商详情页" tabindex="-1">① 投放渠道：抖音短视频 + 电商详情页 <a class="header-anchor" href="#_1-投放渠道-抖音短视频-电商详情页" aria-label="Permalink to &quot;① 投放渠道：抖音短视频 + 电商详情页&quot;">​</a></h3><p><strong>提案里 A 片 / B 片的分工判断成立，不需要改。</strong> 两个渠道正好对应两支片子——A 片进详情页，B 片进抖音信息流，各自的时长与画幅按提案原设定即可。</p><p>仍缺一条：<strong>两者的优先级。</strong> 它决定先做哪支。提案已给出建议——<strong>先做 A 片、B 片从中剪出</strong>，反过来做要重拍。</p><div class="tip custom-block"><p class="custom-block-title">这条回来得很划算</p><p>渠道是原清单 🟢 组（影响判断）里的一项，但它一到手，A 片和 B 片就同时从「待定」变成「可开工」——<strong>只要物料齐</strong>。</p><p><strong>现在挡住项目的已经不是判断，全是物料。</strong></p></div><h3 id="_2-产品未上市-属新品待发" tabindex="-1">② 产品未上市，属新品待发 <a class="header-anchor" href="#_2-产品未上市-属新品待发" aria-label="Permalink to &quot;② 产品未上市，属新品待发&quot;">​</a></h3><p>这一条推翻了上一轮定的自主发掘计划，也带出三个新问题。</p><p><strong>首先，自主发掘这条路基本关掉了。</strong> 原计划靠电商在售链接一次解决三件事——买一杯拍配料表、自购实物做撕封口实拍、抓详情页与买家秀。产品未上市，<strong>这三件全部落空，只能等客户</strong>。</p><div class="danger custom-block"><p class="custom-block-title">三个连带问题，一个比一个靠后但一个比一个贵</p><p><strong>其一，包装设计可能还没定稿。</strong> 未上市新品的包装常常还在改。而「包装设计源文件」是物料清单第 1 项、是最硬的必需项——<strong>如果拿到的不是终稿，包装出镜的所有镜头都要返工</strong>。这条必须问，且要问「是否已终稿」而不是「能不能给」。</p><p><strong>其二，配料表与营养成分表可能尚未定稿。</strong> 新品的标签往往和上市同步敲定。若如此，工艺资料里那批营养表述<strong>不是暂时没数据，是短期内拿不到数据</strong>——这会让第 3 项从「最急」变成「长期阻塞」。</p><p><strong>其三，交期不再由我方工期决定，而由上市节点倒推。</strong> 6 个工作日是物料齐备之后的数字。真正的排期锚点是上市日，且上市日通常不可推迟——<strong>留给物料等待的窗口有多大，取决于这个日期，现在还不知道</strong>。</p></div><h3 id="_3-由此新增的索要项" tabindex="-1">③ 由此新增的索要项 <a class="header-anchor" href="#_3-由此新增的索要项" aria-label="Permalink to &quot;③ 由此新增的索要项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>新增索要</th><th>归属</th></tr></thead><tbody><tr><td>1a</td><td><strong>包装设计是否已终稿</strong>，若未定稿，预计定稿时间</td><td>并入第 1 项</td></tr><tr><td>3a</td><td><strong>配料表与营养成分表是否已定稿</strong></td><td>并入第 3 项</td></tr><tr><td>9</td><td><strong>预计上市时间</strong>（原「交期」项）——由 🟢 升为 🔴</td><td>排期锚点</td></tr><tr><td>——</td><td><strong>上市前的信息披露边界</strong>：产品信息何时可对外</td><td>保密与授权</td></tr></tbody></table><h2 id="教学演示案例被推翻的假设" tabindex="-1">教学演示案例被推翻的假设 <a class="header-anchor" href="#教学演示案例被推翻的假设" aria-label="Permalink to &quot;教学演示案例被推翻的假设&quot;">​</a></h2><p>知识库里的 <a href="/cases/case-04-vf-fries-crisp">案例 04</a> 和 <a href="/cases/case-04-fries-crisp-formats">片型可行性分析</a> 是同题材的<strong>纸上推演</strong>。方法论骨架可以复用，但它的产品设定和真实产品对不上：</p><table tabindex="0"><thead><tr><th>case-04 的假设</th><th>真实产品</th><th>后果</th></tr></thead><tbody><tr><td>袋装零食</td><td><strong>46g 纸杯装</strong></td><td>「倒出」「叠落」动作要重做；<strong>多出一个撕封口的动作</strong>，比推演里的任何动作都好用</td></tr><tr><td>只讲工艺（VF）</td><td>包装主打<strong>原薯鲜切</strong>，无 VF</td><td>创意核心要重新定，不能直接套「展示做法不展示好处」</td></tr><tr><td>无口味设定</td><td><strong>番茄味</strong></td><td>番茄有颜色（红）、有酸甜感、有「番茄酱蘸薯条」的心智，是推演里完全没有的抓手</td></tr><tr><td>投放以电商详情页为主</td><td>46g 即食杯装更像<strong>线下 / 便利店</strong></td><td>片型和时长的判断要跟着变</td></tr><tr><td>无日文元素</td><td>有日文副标</td><td>多一条合规风险，推演里没有</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">这张表是这个工作区最有价值的产出之一</p><p>「纸上推演 vs 真实项目的差距」，只有同时握有两者的人写得出来。</p><p><strong>五条假设，四条错。</strong> 而且错的方式很有规律——<strong>推演倾向于把产品想象成品类的典型形态</strong>（薯片就是袋装、工艺卖点就讲工艺、渠道就是电商），真实产品的具体性总是超出想象。</p><p>项目交付后这条可以脱敏写进 <code>cases/</code>。</p></div><h2 id="未知项清单" tabindex="-1">未知项清单 <a class="header-anchor" href="#未知项清单" aria-label="Permalink to &quot;未知项清单&quot;">​</a></h2><p>按「缺了会怎样」排序，详见 <a href="./02-materials">02 · 物料清单</a>：</p><table tabindex="0"><thead><tr><th>未知</th><th>缺了会怎样</th></tr></thead><tbody><tr><td>包装实拍 / 设计源文件</td><td><strong>成片做不完</strong>——包装出镜这一镜没法做</td></tr><tr><td><s>VF 的书面工艺资料</s> → <strong>本产品的工艺参数与出处</strong></td><td>🟡 2026-08-06 部分到位。原理讲得对了，但拿到的是通用技术介绍，<strong>本产品的参数、出处、脱油工序均未确认</strong>，见上一节</td></tr><tr><td><strong>配料表与营养成分表</strong></td><td>🔴 <strong>升级为最急项</strong>——VF 资料里七条待定表述，五条要靠它才能结案</td></tr><tr><td><s>日文元素的定性</s></td><td>✅ <strong>2026-08-06 已解决：纯装饰，与日本无关系</strong>。调性确定，并新增包装出镜不突出日文的执行约束</td></tr><tr><td><s>投放渠道</s></td><td>✅ <strong>2026-08-06 已解决</strong>——抖音 + 详情页，A/B 分工成立。仅剩优先级待定</td></tr><tr><td><strong>预计上市时间</strong></td><td>🔴 <strong>由交期项升级</strong>——未上市产品的排期锚点是上市日，不是我方工期</td></tr><tr><td>预算</td><td>生成额度与返工余量没法规划</td></tr><tr><td><s>产品是否已上市</s></td><td>✅ <strong>2026-08-06 已解决：未上市</strong>。代价是实物与标签只能等客户，且包装可能未定稿</td></tr><tr><td>「原薯鲜切」与 VF 哪个是客户心中的主卖点</td><td>创意核心定不了</td></tr></tbody></table><h2 id="风险登记" tabindex="-1">风险登记 <a class="header-anchor" href="#风险登记" aria-label="Permalink to &quot;风险登记&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>等级</th><th>现在的处理</th></tr></thead><tbody><tr><td>客户要求做对比片（对比传统油炸）</td><td>高</td><td>提案里<strong>主动挡掉</strong>并说明是法律问题不是创意问题，见 <a href="/cases/case-04-fries-crisp-formats#✕-对比片">片型分析</a></td></tr><tr><td>客户要求说「非油炸」「更健康」「低脂」</td><td>高</td><td>VF 是油炸。提案里先把红线列清楚</td></tr><tr><td>客户期望使用其 VF 材料中的高风险表述</td><td>中 · <strong>已评估，暂不升级</strong></td><td>材料含「不生成丙烯酰胺」「规避致癌风险」「低脂低热量」等表述，但经确认<strong>属对内认知口径，客户未主张进入成片</strong>。提案 v1.0 的内容边界一节已覆盖，不改动</td></tr><tr><td>通用技术资料被当作本产品依据</td><td>中高</td><td>材料讲的是果蔬脆片通用工艺。<strong>不确认出处与本产品参数就引用，等于替客户背书</strong>。已列为索要项 2a–2d</td></tr><tr><td><s>广告暗示日本进口</s></td><td>✅ <strong>已关闭</strong></td><td>已定性为纯装饰。片中不出现日式元素，包装出镜时不突出日文副标</td></tr><tr><td>手上只有渲染图，无法做包装镜头</td><td>中</td><td>物料清单第一条</td></tr><tr><td>卖点在 VF 和鲜切之间摇摆</td><td>中</td><td>提案里给明确建议，让客户拍板</td></tr><tr><td><strong>包装设计尚未定稿，源文件到手后仍会改</strong></td><td><strong>高</strong></td><td>产品未上市，包装常在改。<strong>拿到的若不是终稿，包装镜头全部返工</strong>。已列为索要项 1a</td></tr><tr><td>配料表 / 营养成分表随上市才定稿</td><td>高</td><td>若成立，第 3 项从「最急」变成「长期阻塞」，工艺资料里那批营养表述短期内都用不了。已列为 3a</td></tr><tr><td>排期锚点是上市日，且通常不可推迟</td><td>中高</td><td>6 个工作日是物料齐备之后的数字。<strong>上市日一旦告知，物料等待窗口就成了硬约束</strong></td></tr><tr><td><strong>未上市信息已公开发布在本站</strong></td><td><strong>高 · 待处置</strong></td><td>本项目自己定的规则是「未上市则按机密处理」，而 <code>lab/</code> 为公开板块且已推送远端。<strong>规则触发了但没执行</strong>，见项目首页</td></tr></tbody></table><hr><p><strong>下一步</strong> → <a href="./01-proposal">01 · 提案</a></p>',48))])}const x=a(h,[["render",c]]);export{_ as __pageData,x as default};
